// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 putAmount, uint256 collectAmount) public {
        // Bound inputs to avoid overflow/underflow and to make sense
        putAmount = bound(putAmount, 0, 100 ether);
        collectAmount = bound(collectAmount, 0, 100 ether);
        unlockTime = bound(unlockTime, 0, block.timestamp + 10000);

        // Ensure the caller has enough ether to put
        vm.assume(putAmount <= address(this).balance);

        // Put some ether into the contract to create a balance
        (bool successPut,) = address(c).call{value: putAmount}(abi.encodeWithSignature("Put(uint256)", unlockTime));
        require(successPut);

        // Try to collect
        uint256 initialContractBalance = address(c).balance;
        (bool successCollect,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // If collect failed, contract balance should be unchanged
        if (!successCollect) {
            assertTrue(address(c).balance == initialContractBalance, "Balance changed on failed collect");
        }
    }
}

