        // Restrict to values that cause a revert: either _am > balance or block timestamp <= unlockTime
        // Since balance is 0 initially (no deposits), any _am > 0 causes revert on second check (acc.balance>=_am)
        vm.assume(_am > 0);
        // Keep unlock time in the future to ensure revert on timestamp check if balance >0, but balance is 0 so we revert anyway
        // Record initial MinSum
        uint256 before = c.MinSum();
        // Attempt Collect with _am > 0; will revert because balance is 0
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _am));
        // Assert that if it reverts, MinSum remains unchanged
        assertTrue(!success || c.MinSum() == before);
    }
}

