pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address sender, uint256 unlockTime, uint256 putAmount, uint256 collectAmount) public {
        vm.assume(sender != address(0));
        vm.assume(putAmount > 0);
        vm.assume(putAmount <= address(this).balance);
        vm.assume(collectAmount > 0);
        vm.assume(collectAmount <= putAmount);
        vm.assume(unlockTime <= block.timestamp + 1000000);

        // Fund the test contract and send ether to C via Put
        vm.deal(sender, putAmount);
        vm.prank(sender);
        c.Put{value: putAmount}(unlockTime);

        // Warp to unlock time
        vm.warp(block.timestamp + 1000001);

        uint256 senderBalanceBefore = sender.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Attempt Collect
        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        if (success) {
            uint256 senderBalanceAfter = sender.balance;
            uint256 contractBalanceAfter = address(c).balance;
            // The sum of sender's balance and contract balance should be conserved
            assertTrue(senderBalanceBefore + contractBalanceBefore == senderBalanceAfter + contractBalanceAfter);
        } else {
            // If revert, balances unchanged
            uint256 senderBalanceAfter = sender.balance;
            uint256 contractBalanceAfter = address(c).balance;
            assertTrue(senderBalanceBefore == senderBalanceAfter && contractBalanceBefore == contractBalanceAfter);
        }
    }
}

