    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 putAmount, uint256 collectAmount, uint256 unlockTimeOffset) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        putAmount = bound(putAmount, 1, 100 ether);
        unlockTimeOffset = bound(unlockTimeOffset, 0, 10000);
        vm.deal(caller, putAmount);
        vm.prank(caller);
        c.Put(block.timestamp + unlockTimeOffset);

        bool reverted = false;
        vm.prank(caller);
        try c.Collect(collectAmount) {
            // success, check that balance before was >= MinSum
            // We can't read internal state directly, but we can infer: if Collect succeeded, the pre-condition required acc.balance >= MinSum
            // So the property is: after a successful Collect, the balance must have been at least MinSum before the call.
            // Since we can't observe the balance before, we check that the balance after is at least MinSum - collectAmount (if collectAmount <= balance) 
            // But a simpler approach: the Collect function only decreases balance if it succeeds, and the condition required balance >= MinSum before.
            // So we assert that the caller's balance after Collect is less than or equal to their previous balance minus MinSum? Not exactly.
            // Better: The property can be rephrased as: If Collect does not revert, then the caller's balance before the call must have been >= MinSum.
            // Since we cannot read balance before, we use the fact that the caller must have had at least MinSum balance in the contract before the call.
            // We can verify by checking that either the caller's balance after is >= MinSum (if collectAmount <= 0) or some other invariant.
            // But the simplest observable consequence is: if Collect succeeds, then before the call, acc.balance >= MinSum, and after the call, acc.balance = before - collectAmount, so after balance can be less than MinSum.
            // So we need a different observable rule: After a successful Collect, the total balance of all holders (sum of Acc balances) is at least MinSum for any holder that still has balance? No.
            // Let's use: If Collect succeeds, then the caller's balance in the contract after the call must be < MinSum only if collectAmount > 0, but that's not a general rule.
            // Actually the intended property: The reference requires balance >= MinSum before Collect can succeed. So if we can observe that a successful Collect implies that the caller previously deposited at least MinSum? That's not directly observable.
            // So we need an observable state after the call that distinguishes: In reference, after Collect succeeds, the balance before was >= MinSum, so the decrease is at most balance - MinSum. But we can't observe that.
            // Let's use a different approach: The only public getter that tells us about the balance is Acc mapping. We can read Acc(caller).balance after the call.
            // If Collect succeeded, then in the reference, before the call, acc.balance >= MinSum, so after the call, acc.balance = previousBalance - collectAmount. Since previousBalance >= MinSum, we have if collectAmount <= previousBalance - MinSum, then acc.balance after >= MinSum.
            // This is not a guaranteed invariant.
            // The correct invariant: In the reference, if Collect does not revert, then the caller must have had at least MinSum before. So if we see a successful Collect, we can assert that the caller's balance after the call plus collectAmount is >= MinSum. But we can't know collectAmount if it reverts? We do know collectAmount from the fuzz.
            // So: After a successful Collect, Acc(caller).balance + collectAmount >= MinSum.
            uint256 balanceAfter = c.Acc(caller).balance;
            assertTrue(balanceAfter + collectAmount >= 1 ether, "Balance before must have been >= MinSum");
        } catch {
