pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        vm.assume(amount > 0 && amount <= c.MinSum()); // Ensure Collect can be attempted
        vm.assume(unlockTime < block.timestamp); // Ensure unlock condition passes
        vm.deal(address(this), amount);
        c.Put{value: amount}(unlockTime);

        // Deploy a reentrant contract to call Collect
        Reentrant attacker = new Reentrant(address(c));
        vm.deal(address(attacker), amount);
        attacker.attack{value: amount}(amount, unlockTime);

        // After the attack, check that the balance of the attacker in the contract didn't decrease
        assertTrue(c.Acc(address(attacker)).balance == amount);
    }
}

contract Reentrant {
    C public target;
    bool public reentered;

    constructor(address _target) {
        target = C(_target);
    }

    function attack(uint256 amount, uint256 unlockTime) external payable {
        target.Put{value: amount}(unlockTime);
        // This call will try to reenter Collect
        (bool success, ) = address(target).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", amount));
        reentered = !success;
    }

    receive() external payable {
        if (!reentered) {
            // Attempt reentrancy
            (bool success, ) = address(target).call(abi.encodeWithSignature("Collect(uint256)", 0));
            reentered = !success;
        }
    }
}

