    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 putAmount, uint256 collectAmount) public {
        vm.assume(putAmount > 0);
        vm.assume(collectAmount > 0);

        // Ensure enough ETH
        vm.deal(address(this), putAmount + 1 ether);

        // Call Put to set balance
        c.Put(unlockTime);

        // Call Collect
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // The general rule: MinSum should always be 1 ether (its initial value)
        assertTrue(c.MinSum() == 1 ether);
    }
}

