pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initialDeposit, uint256 unlockTime) public {
        // Bound inputs to reasonable values
        initialDeposit = bound(initialDeposit, 0, 100 ether);
        unlockTime = bound(unlockTime, 0, 1000000);

        // First make a deposit to set balance
        vm.deal(address(this), initialDeposit);
        c.Put{value: initialDeposit}(unlockTime);

        // Try Collect with an amount that exceeds MinSum (we want it to revert due to balance < MinSum when MinSum is increased)
        // We'll use a fixed _am that is less than initialDeposit but greater than MinSum in the mutated version
        uint256 collectAmount = initialDeposit > 0 ? initialDeposit / 2 : 0;

        // This call should revert if collectAmount < MinSum (which happens with MinSum=2 ether when balance is small)
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // After the call, MinSum should still be its initial value (1 ether in reference, 2 ether in mutant)
        // The rule: MinSum is always 1 ether or 2 ether (it never changes from constructor initialization)
        assertTrue(c.MinSum() == 1 ether || c.MinSum() == 2 ether);
    }
}

