pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 _am, uint256 deposit) public {
        vm.assume(_am > 0);
        vm.assume(deposit >= _am);
        vm.assume(deposit <= 100 ether);
        vm.assume(caller != address(0));
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Put{value: deposit}(0);
        uint256 balanceBefore = c.Acc(caller).balance;
        vm.warp(block.timestamp + 1);
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _am));
        if (success) {
            uint256 balanceAfter = c.Acc(caller).balance;
            assertTrue(balanceAfter == balanceBefore - _am, "balance not decremented by _am");
        }
    }
}

